{
  "type_map": {},
  "constraints": [
    {
      "id": "R1",
      "category": "count_semantics",
      "alternatives": [
        "df['ct_srv_src'] <= df['ct_src_ltm']"
      ],
      "features": ["ct_srv_src", "ct_src_ltm"],
      "rationale": "ct_srv_src counts connections with same service and source address, which is a subset of connections with same source address (ct_src_ltm)."
    },
    {
      "id": "R2",
      "category": "count_semantics",
      "alternatives": [
        "df['ct_srv_dst'] <= df['ct_dst_ltm']"
      ],
      "features": ["ct_srv_dst", "ct_dst_ltm"],
      "rationale": "ct_srv_dst counts connections with same service and destination address, which is a subset of connections with same destination address (ct_dst_ltm)."
    },
    {
      "id": "R3",
      "category": "count_semantics",
      "alternatives": [
        "df['ct_src_dport_ltm'] <= df['ct_src_ltm']"
      ],
      "features": ["ct_src_dport_ltm", "ct_src_ltm"],
      "rationale": "ct_src_dport_ltm counts connections with same source address and destination port, which is a subset of connections with same source address (ct_src_ltm)."
    },
    {
      "id": "R4",
      "category": "count_semantics",
      "alternatives": [
        "df['ct_dst_sport_ltm'] <= df['ct_dst_ltm']"
      ],
      "features": ["ct_dst_sport_ltm", "ct_dst_ltm"],
      "rationale": "ct_dst_sport_ltm counts connections with same destination address and source port, which is a subset of connections with same destination address (ct_dst_ltm)."
    },
    {
      "id": "R5",
      "category": "count_semantics",
      "alternatives": [
        "df['ct_dst_src_ltm'] <= df['ct_src_ltm']"
      ],
      "features": ["ct_dst_src_ltm", "ct_src_ltm"],
      "rationale": "ct_dst_src_ltm counts connections with same source and destination address, which is a subset of connections with same source address (ct_src_ltm)."
    },
    {
      "id": "R6",
      "category": "count_semantics",
      "alternatives": [
        "df['ct_dst_src_ltm'] <= df['ct_dst_ltm']"
      ],
      "features": ["ct_dst_src_ltm", "ct_dst_ltm"],
      "rationale": "ct_dst_src_ltm counts connections with same source and destination address, which is a subset of connections with same destination address (ct_dst_ltm)."
    },
    {
      "id": "R7",
      "category": "count_semantics",
      "alternatives": [
        "df['ct_src_ltm'] + df['ct_dst_ltm'] - df['ct_dst_src_ltm'] <= 100"
      ],
      "features": ["ct_src_ltm", "ct_dst_ltm", "ct_dst_src_ltm"],
      "rationale": "The union of connections with same source or same destination (inclusion-exclusion) cannot exceed the total window size of 100 connections."
    }
  ]
}
